import type { LatLon } from "./geo";
import type { Locale, Localized } from "./i18n";
import data from "./data/countries.json";

// data/countries.json is generated by scripts/build-countries.mjs from the
// world map — don't edit it by hand; fix names and borders in the script.

export type Country = LatLon & {
  /** ISO 3166-1 alpha-2, lower case: "br". */
  id: string;
  name: Localized;
  /** Other names a player may type: "USA", "Holland". */
  also?: string[];
  /** The map shapes (by name in the world map's data) that make up the country. */
  shapes: string[];
  /** The mainland's bounding box: west, south, east, north. */
  box: number[];
  /** Square kilometres. */
  area: number;
  /** The countries it shares a land border with. */
  borders: string[];
};

export const COUNTRIES = data as Country[];

const byId = new Map(COUNTRIES.map((country) => [country.id, country]));

export const countryById = (id: string): Country | undefined => byId.get(id);

/** Two opposite corners of the country's mainland, for framing it on the map. */
export function cornersOf(country: Country): LatLon[] {
  const [west, south, east, north] = country.box;
  // A box that crosses the antimeridian can't be framed by its corners.
  if (west > east) return [country];
  return [
    { lat: south, lon: west },
    { lat: north, lon: east },
  ];
}

// "Côte d'Ivoire" matches "cote d ivoire".
const fold = (text: string) =>
  text
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

const searchKeys = new Map(
  COUNTRIES.map((country) => [
    country.id,
    [country.name.en, country.name.pt, ...(country.also ?? [])].map(fold),
  ]),
);

/**
 * The countries of `pool` a typed name could mean, best match first: names
 * that start with the text, then names with a word that does, then the rest.
 */
export function searchCountries(query: string, pool: readonly Country[], locale: Locale): Country[] {
  const text = fold(query);
  if (!text) return [];
  const ranked: { country: Country; rank: number }[] = [];
  for (const country of pool) {
    const keys = searchKeys.get(country.id) ?? [];
    const own = fold(country.name[locale]);
    const rank = own.startsWith(text)
      ? 0
      : keys.some((key) => key.startsWith(text))
        ? 1
        : keys.some((key) => key.includes(` ${text}`))
          ? 2
          : keys.some((key) => key.includes(text))
            ? 3
            : -1;
    if (rank >= 0) ranked.push({ country, rank });
  }
  return ranked
    .sort((a, b) => a.rank - b.rank || a.country.name[locale].localeCompare(b.country.name[locale], locale))
    .map((entry) => entry.country);
}

// ── The borders as a graph ──────────────────────────────────────────────────

const stepsCache = new Map<string, Map<string, number>>();

/**
 * How many borders lie between `from` and every country that can be reached
 * overland from it (itself included, at 0).
 */
export function stepsFrom(from: string): Map<string, number> {
  const cached = stepsCache.get(from);
  if (cached) return cached;
  const steps = new Map([[from, 0]]);
  const queue = [from];
  for (let i = 0; i < queue.length; i++) {
    const here = queue[i];
    for (const next of byId.get(here)?.borders ?? []) {
      if (!steps.has(next)) {
        steps.set(next, (steps.get(here) ?? 0) + 1);
        queue.push(next);
      }
    }
  }
  stepsCache.set(from, steps);
  return steps;
}

/** Whether `to` can be reached from `from` crossing only the countries in `open`. */
export function isConnected(from: string, to: string, open: ReadonlySet<string>): boolean {
  const seen = new Set([from]);
  const queue = [from];
  for (let i = 0; i < queue.length; i++) {
    for (const next of byId.get(queue[i])?.borders ?? []) {
      if (next === to) return true;
      if (open.has(next) && !seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }
  return false;
}

/**
 * A shortest way overland from `from` to `to`, both ends included. Where
 * several are as short, the one through the most countries in `prefer` wins.
 */
export function shortestRoute(from: string, to: string, prefer: ReadonlySet<string> = new Set()): string[] {
  const toGo = stepsFrom(to);
  if (!toGo.has(from)) return [];
  // Best number of preferred countries from each country onwards, by dynamic
  // programming from the destination outwards.
  const order = [...toGo.entries()].sort((a, b) => a[1] - b[1]).map(([id]) => id);
  const best = new Map<string, { liked: number; next: string | null }>();
  for (const id of order) {
    const here = toGo.get(id) ?? 0;
    let choice: { liked: number; next: string | null } = { liked: 0, next: null };
    for (const next of byId.get(id)?.borders ?? []) {
      if (toGo.get(next) !== here - 1) continue;
      const liked = (best.get(next)?.liked ?? 0) + (prefer.has(next) ? 1 : 0);
      if (choice.next === null || liked > choice.liked) choice = { liked, next };
    }
    best.set(id, choice);
  }
  const route = [from];
  for (let at = best.get(from)?.next; at; at = best.get(at)?.next) route.push(at);
  return route;
}
